  logger.info(`User list requested by ${req.ip}`);

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### 9. Add Process Security

```javascript
// Ensure secure process configuration
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception:', err);
  // Graceful shutdown
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error to trigger the uncaughtException handler
  setTimeout(() => { throw reason; }, 100);
});

// Set Node.js to use secure TLS version
process.env.NODE_TLS_REJECT_UNAUTHORIZED = '1';
```

### 10. Environment Configuration

Create a `.env` file and use `dotenv`:

```bash
npm install dotenv
```

Create `.env`:
```
