const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, validationResult, param } = require('express-validator');

const app = express();

// Middleware for parsing JSON and URL-encoded bodies
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Security middleware
app.use(helmet()); // Set security-related HTTP headers

// CORS configuration
const corsOptions = {
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// HTTP request logging
app.use(morgan('combined'));

// Centralized error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Custom error responses based on error type
  if (err.type === 'entity.parse.error') {
    return res.status(400).json({ error: 'Bad request - invalid JSON format' });
  }

  if (err instanceof SyntaxError) {
    return res.status(400).json({ error: 'Bad request - invalid JSON syntax' });
  }

  // Default error response
  res.status(500).json({ 
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// Health endpoint with validation
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with input validation
app.get('/users', 
  // Optional query parameter validation
  [
    param('id').optional().isInt().withMessage('ID must be an integer'),
    param('name').optional().isString().withMessage('Name must be a string')
  ],
  (req, res, next) => {
    try {
      // Run validation
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      // In a real application, this would fetch from a database
      // For demonstration, we'll return mock data with optional filtering
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply optional filtering based on validated parameters
      if (req.query.id) {
        users = users.filter(user => user.id === parseInt(req.query.id));
      }

      if (req.query.name) {
        users = users.filter(user => user.name.toLowerCase().includes(req.query.name.toLowerCase()));
      }

      res.json(users);
    } catch (error) {
      next(error); // Pass to centralized error handler
    }
  }
);

// Add a protected endpoint to demonstrate authentication
app.get('/admin', 
  // In a real app, you would have proper authentication middleware here
  (req, res) => {
    res.status(403).json({ error: 'Forbidden - Admin access required' });
  }
);

// Handle 404 errors
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', message: `Cannot ${req.method} ${req.url}` });
});

// Start server with proper error handling
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.syscall !== 'listen') {
    throw error;
  }

  const address = server.address();
  const bind = typeof address === 'string' ? `pipe ${address}` : `port ${address.port}`;

  // Handle specific port errors
  if (error.code === 'EACCES') {
    console.error(`${bind} requires elevated privileges`);
    process.exit(1);
  } else if (error.code === 'ADDR_INUSE') {
    console.error(`${bind} is already in use`);
    process.exit(1);
  } else {
    throw error;
  }
});

module.exports = app;

