  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

// Request logging
app.use(morgan('combined'));

// Input sanitization to prevent XSS
app.use(sanitizeHtml({
  allowedTags: [], // Remove all HTML tags
  allowedAttributes: {}
}));

// JSON parser with size limits to prevent DoS
app.use(express.json({ limit: '1kb' }));

// Custom error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});

// Health endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // In a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate output to ensure no sensitive data leakage
    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // Email might be considered sensitive in some contexts
      // Consider removing or hashing in production
    }));

    res.json(safeUsers);
  } catch (error) {
    console.error('Users fetch error:', error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// Add a catch-all route for undefined endpoints
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Start server with proper error handling
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle server errors
server.on('error', (error) => {
  if (error.syscall !== 'listen') {
    throw error;
  }

  const address = server.address();
  const bind = typeof address === 'string' ? `pipe ${address}` : `port ${address.port}`;

  // Handle specific listen errors with friendly messages
  switch (error.code) {
    case 'EACCES':
      console.error(`${bind} requires elevated privileges`);
      process.exit(1);
      break;
    case 'ADDR_INUSE':
      console.error(`${bind} is already in use`);
      process.exit(1);
      break;
    default:
      throw error;
  }
});

module.exports = app;

